// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · TYT Türkçe: sözcükte ve cümlede anlam (her soru kendi cümlesini içerir) (zor).
const ozExam1Zor = <(String, String, List<String>, String)>[
  ('Aşağıdaki cümlelerin hangisinde "kol" sözcüğü yan anlamıyla kullanılmamıştır?', 'Düşünce kolunu alçıya aldılar.', ['Ceketin kolu biraz kısa gelmiş.', 'Koltuğun kolu yerinden çıkmış.', 'Nehrin bir kolu köyün içinden geçiyordu.'], 'Alçıya alınan kol, insanın organıdır; bu gerçek anlamdır. Ceket, koltuk ve nehir kolunda biçim ya da işlev benzerliğinden doğan yan anlam vardır.'),
  ('"Ayak" sözcüğü aşağıdaki cümlelerin hangisinde ötekilerden farklı bir anlam türüyle kullanılmıştır?', 'Koşarken ayağı burkuldu.', ['Masanın bir ayağı kısa olduğu için sallanıyordu.', 'Merdivenin son ayağında durdu.', 'Köprünün ayakları sel suyuyla aşınmıştı.'], 'İlk cümlede ayak, vücut organı olarak gerçek anlamdadır. Masa, merdiven ve köprü için kullanılan "ayak" ise benzerlikten doğan yan anlamdır.'),
  ('"Ağır" sözcüğü aşağıdaki cümlelerin hangisinde "hafif" sözcüğünün karşıtı olarak değil, "hızlı" sözcüğünün karşıtı olarak kullanılmıştır?', 'Kaplumbağa ağır adımlarla yola devam etti.', ['Ağır yükü sırtlanan hamal soluk soluğa kaldı.', 'Ağır bir taşı yerinden kaldıramadı.', 'Valizin ağır olduğunu görünce yardım etti.'], 'Ağır adımlar yavaş adımlardır; burada sözcük "hızlı"nın karşıtıdır. Diğerlerinde kütlesi fazla olma anlamı, yani "hafif"in karşıtı vardır.'),
  ('"Açık" sözcüğünün karşıtı, aşağıdaki cümlelerin hangisinde "kapalı" olamaz?', 'Açık renkli bir gömlek giymişti.', ['Kapı açık kalmış, içeri kedi girmiş.', 'Bugün hava açık, yürüyüşe çıkabiliriz.', 'Market gece yarısına kadar açık.'], 'Açık renk koyu rengin karşıtıdır; "kapalı renk" denmez. Kapı, hava ve dükkân için "kapalı" karşıtı kullanılabilir.'),
  ('"Yüz" sözcüğü aşağıdakilerin hangisinde ötekilerle sesteş olup anlamca ilgisizdir?', 'Göl çok soğuktu, biraz yüzüp çıktık.', ['Yüzünü görmek için başını kaldırdı.', 'Kumaşın yüzü pürüzsüzdü.', 'Elbisenin yüzü astarından açık renkteydi.'], '"Yüzmek" eyleminin kökü olan "yüz", organ ve bir şeyin dış yüzü anlamındaki "yüz" ile yalnız ses bakımından aynıdır; anlamca bağı yoktur.'),
  ('"Rüzgâr" sözcüğü için aşağıdakilerden hangisi doğrudur?', 'Görülmese de dokunma duyusuyla algılandığı için somuttur.', ['Gözle görülmediği için beş duyunun dışında kalan soyut bir sözcüktür.', 'Hem somut hem soyut olan tek sözcüktür.', 'Yalnızca mecaz anlamda kullanılabilir.'], 'Somutluk için beş duyudan biriyle algılanmak yeterlidir. Rüzgâr tenimizde hissedildiği ve sesi duyulduğu için somuttur.'),
  ('Aşağıdaki cümlelerin hangisinde "meyve" sözcüğü genel bir kavram olarak, bir türü kapsayacak biçimde kullanılmıştır?', 'Pazardan meyve alacaksan bana birkaç kayısı da al.', ['Bu kitap yıllarca süren emeğin meyvesidir.', 'Sabrın meyvesini yıllar sonra o güzel haberle topladı.', 'Çalışmalarının meyvesi bu ödüldü.'], 'İlk cümlede meyve, kayısıyı da içine alan genel bir kavramdır. Diğerlerinde "sonuç, ürün" anlamında mecaz kullanım vardır.'),
  ('Aşağıdaki cümlelerin hangisinde ad aktarması yoktur?', 'Bahçedeki elma ağacı bu yıl çok meyve verdi.', ['Salon, konuşmacıyı ayakta alkışladı.', 'Bütün mahalle, kızlarının düğününe davetli olarak katıldı.', 'Bir tencere yemeği tek başına bitirdi.'], 'Salon (oradaki insanlar), mahalle (mahalleli) ve tencere (içindeki yemek) ad aktarmasıdır. Elma ağacının meyve vermesi gerçek bir anlatımdır.'),
  ('Aşağıdakilerin hangisinde dolaylama yapılmamıştır?', 'Bal arısı - arı', ['Aslan - hayvanlar kralı', 'Ankara - başkent', 'Kuran - kutsal kitap'], '"Bal arısı" bir arı türünün doğrudan adıdır; arıyı dolaylı anlatmak için kullanılmaz. Hayvanlar kralı, başkent ve kutsal kitap dolaylı anlatımlardır.'),
  ('"İstanbul\'un görülecek yerlerinden biri de Kız Kulesi\'dir." cümlesinde İstanbul yerine aşağıdakilerden hangisi kullanılırsa dolaylama yapılmış olur?', 'Boğaz\'ın incisi', ['Marmara Bölgesi', 'Türkiye\'nin bir ili', 'Batıdaki büyük kent'], '"Boğaz\'ın incisi", İstanbul\'u adını anmadan, ona özgü bir nitelikle anlatan dolaylamadır. Diğerleri birçok yeri kapsayabilecek tanımlamalardır.'),
  ('Yılandan çok korkan bir köylünün, ondan söz ederken adını anmayıp "yerin altındaki" demesi hangi anlatım yoluna örnektir?', 'Güzel adlandırma', ['Ad aktarması', 'Sesteşlik', 'Abartma'], 'Korkulan bir varlığın asıl adını anmaktan kaçınıp ona dolaylı ve yumuşak bir ad vermek güzel adlandırmadır.'),
  ('Aşağıdaki cümlelerin hangisinde bir sesin yansımasından türemiş sözcük mecaz anlamda kullanılmıştır?', 'Bu haber kulağıma çalınınca içim cız etti.', ['Tavadaki yağ cızırdamaya başladı.', 'Ateşe atılan dal çıtırdadı.', 'Eski buzdolabı gece boyunca hiç durmadan vızıldadı.'], '"İçi cız etmek" birden üzülmek anlamına gelen mecaz bir kullanımdır. Diğerlerinde ses yansımaları gerçek seslere karşılık gelir.'),
  ('"Yorgun argın eve döndüğünde sofrayı kurulmuş buldu." cümlesindeki ikilemeyle ilgili aşağıdakilerden hangisi doğrudur?', 'Yakın anlamlı iki sözcükten oluşup yorgunluğu pekiştirir.', ['Karşıt anlamlı iki sözcükten oluşup yaklaşıklık bildirir.', 'Ses yansımalı sözcüklerden oluşup bir sesi taklit eder ve eylemin nasıl yapıldığını bildirir.', 'Biri anlamsız iki sözcükten oluşup bir topluluğu anlatır.'], '"Argın" da yorgun demektir; anlamca yakın iki sözcük bir araya gelerek yorgunluğun derecesini güçlendirmiştir.'),
  ('Aşağıdaki cümlelerin hangisinde "yapacak işin çok olması" anlamını taşıyan bir deyim kullanılmıştır?', 'Teslim tarihi gelince işler başımızdan aşkın oldu.', ['Bu işin altından kalkamayacağını biliyordu.', 'Söyleyeceklerini dilinin altında sakladı.', 'Ondan hiç umudu kalmamıştı, sonunda elini eteğini çekti.'], '"Başından aşkın olmak", yapacak işin çok olması, işlere yetişememe anlamındadır.'),
  ('Aşağıdaki cümlelerin hangisinde deyim, anlamına uygun olmayan bir bağlamda kullanılmıştır?', 'Sınavda yüksek not alınca etekleri tutuştu.', ['Yangını görünce yüreği ağzına geldi.', 'Yanlışını anlayınca yerin dibine geçti.', 'Yalanı ortaya çıkınca kıpkırmızı kesildi, yüzü kızardı.'], '"Etekleri tutuşmak" telaşa ve korkuya kapılmak demektir; yüksek not alma sevinçli bir durumdur. Bu yüzden deyim bağlama uymaz.'),
  ('Aşağıdaki atasözlerinden hangisi ötekilerle aynı düşünceyi paylaşmaz?', 'Ne ekersen onu biçersin.', ['Üzüm üzüme baka baka kararır.', 'Körle yatan şaşı kalkar.', 'Bana arkadaşını söyle, sana kim olduğunu söyleyeyim.'], 'Diğer üç atasözü, insanın birlikte olduğu kişilerden etkilendiğini anlatır. "Ne ekersen onu biçersin" ise yapılan işin karşılığının alınacağını söyler.'),
  ('Bir duyu organıyla algılanan niteliğin başka bir duyunun alanına taşınmadığı, yani her şeyin kendi duyusuyla anlatıldığı cümle hangisidir?', 'Fırından çıkan ekmeğin sıcaklığı ellerimi ısıttı.', ['Acı bir çığlık sessizliği bozdu.', 'Keskin bir koku burnuma çarptı.', 'Sert bir sesle bize bağırarak odadan çıkmamızı istedi.'], 'Sıcaklığın elleri ısıtması, aynı duyu (dokunma) içinde kalır. Diğerlerinde tat, dokunma nitelikleri ses ve kokuya aktarılmıştır.'),
  ('Ev sahibimiz bizi kapıda "sıcak bir gülümsemeyle" karşıladı. Bu sözdeki "sıcak" nitelemesi nasıl bir anlatım özelliği taşır?', 'Dokunma duyusuna ait bir nitelik, görülen bir davranışa aktarılmıştır.', ['Tat duyusuna ait bir nitelik, kokuya aktarılmıştır.', 'Sözcük, terim anlamıyla fizikte ölçülebilen ısıyı anlatmaktadır.', 'Sözcük, bir sesin yansıması olarak kullanılmıştır.'], 'Sıcaklık dokunmayla algılanır; gülümseme ise görülür. Bu bir duyular arası aktarmadır ve aynı zamanda "içten" anlamında mecaz anlam taşır.'),
  ('Aşağıdaki cümlelerin hangisinde bir sözcük, ses bakımından benzediği başka bir sözcüğün yerine yanlışlıkla kullanılmıştır?', 'Doktor, hastasına her gün yürüyüş yapmasını önemsedi.', ['Öğretmen bize bu romanı okumamızı önerdi.', 'Babam, sağlığına çok önem verir.', 'Annem, sağlıklı beslenme konusuna büyük önem veriyor.'], 'Bir şeyi yapmayı tavsiye etmek "önermek"tir; "yürüyüş yapmasını önemsedi" denince "önemsemek" yanlış anlamda kullanılmış olur.'),
  ('Aşağıdaki cümlelerin hangisinde "için" sözcüğü amaç değil, neden bildirmektedir?', 'Hava çok soğuk olduğu için dışarı çıkmadık.', ['Erken uyanmak için alarm kurdu.', 'Kitap almak için kırtasiyeye gitti.', 'Kilo vermek için spor salonuna yazıldı.'], '"Soğuk olduğu için" gerçekleşmiş bir durumu, yani nedeni anlatır. Diğerlerinde ulaşılmak istenen hedef, yani amaç vardır.'),
  ('Aşağıdaki cümlelerin hangisinde koşul anlamı, "-sa / -se" eki kullanılmadan sağlanmıştır?', 'Ödevini bitirdiğin takdirde dışarı çıkabilirsin.', ['Erken gelirsen seninle sinemaya gideriz.', 'Kitabı okursan bana da anlat.', 'Hava güzel olursa pikniğe gideriz.'], '"-dığı takdirde" kalıbı da koşul bildirir. Diğer cümlelerde koşul "-sa/-se" ekiyle kurulmuştur.'),
  ('"Bu ilacı aç karnına içmen gerekiyor, yoksa miden ağrır." cümlesinde "yoksa" sözcüğüyle hangi anlam ilişkisi kurulmuştur?', 'Bir koşul yerine gelmezse ortaya çıkacak sonuç', ['İki durum arasındaki benzerliğin vurgulanması', 'Bir olayın gerçekleşme zamanının belirtilmesi', 'Bir eylemin yapılış amacının açıklanması'], '"Yoksa", "aç karnına içmezsen" anlamında olumsuz bir koşul kurar ve bunun sonucunu bildirir.'),
  ('"Komşumuz, yeni bir ev almak amacıyla yıllardır para biriktiriyordu." Bu cümleye en yakın anlamlı cümle hangisidir?', 'Komşumuz, yeni bir ev alabilmek için yıllardır para biriktiriyordu.', ['Komşumuz, yeni bir ev aldığı için yıllardır para biriktiriyordu.', 'Komşumuz yeni bir ev alırsa yıllarca para biriktirecek.', 'Komşumuz para biriktirdiği için yeni bir ev aldı.'], '"Amacıyla" ile "alabilmek için" aynı amaç ilişkisini kurar. Diğer seçenekler neden ya da koşul bildirerek anlamı değiştirir.'),
  ('"Yağmur yağdığından maç ertelendi." ve "Maçın ertelenmemesi için yağmurun dinmesini bekledik." cümleleri karşılaştırıldığında hangisi söylenebilir?', 'İlki neden-sonuç, ikincisi amaç-sonuç ilişkisi taşır.', ['İkisi de koşul-sonuç ilişkisi taşır.', 'İlki amaç-sonuç, ikincisi neden-sonuç ilişkisi taşır.', 'İkisinde de iki durum birbiriyle karşılaştırılmıştır.'], 'İlk cümlede ertelemenin gerçek nedeni yağmurdur. İkincide bekleme eylemi, maçın ertelenmemesi hedefine yöneliktir.'),
  ('"Ağaçlar kesildikçe toprak erozyona daha açık hâle geliyor." cümlesinde vurgulanan anlam ilişkisi hangisidir?', 'Bir durumun artmasına bağlı olarak başka bir durumun da artması', ['Bir eylemin belirli bir amaçla yapılması', 'İki varlığın üstünlük bakımından kıyaslanması', 'Bir olayın gerçekleşmesinin kesin olmaması'], '"-dıkça" eki, ağaç kesiminin arttığı ölçüde erozyon riskinin de arttığını, yani orantılı bir neden-sonuç ilişkisini anlatır.'),
  ('"Kuraklık sürdüğü için barajlardaki su seviyesi düştü, bu yüzden de şehirde su kesintileri başladı." cümlesinde kaç tane neden-sonuç ilişkisi vardır?', 'İki', ['Bir', 'Üç', 'Dört'], 'Kuraklık su seviyesinin düşmesine, su seviyesinin düşmesi de kesintilere yol açmıştır; zincirleme iki neden-sonuç ilişkisi vardır.'),
  ('"Kaleci son dakikada penaltıyı kurtarmasaydı takımımız kupayı kaybedecekti." cümlesinden hangisi kesin olarak anlaşılır?', 'Kaleci penaltıyı kurtarmıştır.', ['Takım kupayı kaybetmiştir.', 'Penaltı maçın ilk dakikalarında atılmıştır.', 'Kaleci penaltıyı kurtaramamıştır ve üzgündür.'], '"Kurtarmasaydı ... kaybedecekti" yapısı gerçekleşmemiş bir koşulu anlatır; demek ki kaleci penaltıyı kurtarmış ve takım kupayı kazanmıştır.'),
  ('"Kardeşim, benden daha az kitap okur ama okuduklarını daha iyi anlar." cümlesinde kaç ayrı yönden karşılaştırma yapılmıştır?', 'İki', ['Bir', 'Üç', 'Dört'], 'Kardeşler hem okunan kitap miktarı (daha az) hem de anlama düzeyi (daha iyi) bakımından karşılaştırılmıştır.'),
  ('"Şairin son kitabı, ilk kitapları kadar ilgi görmedi." cümlesinden hangisi çıkarılabilir?', 'Şairin ilk kitapları son kitabından daha çok ilgi görmüştür.', ['Şairin son kitabı hiç okunmamıştır.', 'Şairin ilk kitapları da ilgi görmemiştir.', 'Şair, son kitabının ilgi görmemesi üzerine bir daha kitap yazmamıştır.'], '"... kadar ilgi görmedi" yapısı, son kitabın ilgisinin ilk kitaplardan az olduğunu söyler; ilgi görmediği anlamına gelmez.'),
  ('Aşağıdaki cümlelerin hangisinde, içinde "en" sözcüğü bulunmasına rağmen yargı nesneldir?', 'Dünya\'nın en yüksek dağı Everest\'tir.', ['Dünya\'nın en güzel manzarası buradadır.', 'Bu, okuduğum en sürükleyici romandı.', 'Annemin yaptığı en lezzetli yemek mantıdır.'], 'Everest\'in deniz seviyesine göre en yüksek dağ olduğu ölçümle kanıtlanmıştır. Diğerleri beğeniye dayalı öznel yargılardır.'),
  ('"Kediler köpeklerden daha bağımsız hayvanlardır." cümlesiyle "Kediler köpeklerden daha sevimlidir." cümlesi arasındaki fark için hangisi söylenebilir?', 'İkincisi tümüyle beğeniye dayanırken ilki gözleme dayalı bir genellemedir.', ['İkisi de kesin olarak kanıtlanmış bilimsel bilgilerdir.', 'İlki tümüyle beğeniye dayanırken ikincisi ölçülebilir ve kanıtlanmış bir bilgidir.', 'İkisinde de karşılaştırma yapılmamıştır.'], '"Sevimli" tamamen kişisel bir beğeni bildirir. "Bağımsız" ise davranış gözlemlerine dayanan bir genellemedir; iki cümle de karşılaştırma içerir.'),
  ('"Bu sabah servis gecikmeseydi sınava zamanında yetişirdim." cümlesinden hangisi kesin olarak çıkarılabilir?', 'Konuşan sınava geç kalmıştır.', ['Servis zamanında gelmiştir.', 'Konuşan sınava hiç girmemiştir.', 'Servis her sabah gecikir.'], 'Gerçekleşmemiş koşul bildiren yapı, servisin geciktiğini ve konuşanın sınava geç kaldığını gösterir. Sınava hiç girmediği ise kesin değildir.'),
  ('"Ancak bu yıl ilk kez yüzme yarışmasında derece alabildi." cümlesinden aşağıdakilerden hangisi çıkarılamaz?', 'Bu yıl yarışmaya katılmamıştır.', ['Daha önceki yarışmalarda derece alamamıştır.', 'Derece almak için uzun süre uğraşmıştır.', 'Bu yıl bir derece elde etmiştir.'], 'Cümle bu yıl derece aldığını söyler; demek ki yarışmaya katılmıştır. "Ancak" ve "ilk kez" önceki başarısızlıkları ve süren çabayı sezdirir.'),
  ('"O da sonunda gerçeği anladı." cümlesiyle ilgili aşağıdakilerden hangisi söylenemez?', 'Gerçeği herkesten önce anlamıştır.', ['Gerçeği anlayan başkaları da vardır.', 'Gerçeği anlaması zaman almıştır.', 'Artık gerçeği bilmektedir.'], '"De" başkalarının da anladığını, "sonunda" ise bunun geciktiğini sezdirir. Bu yüzden onun herkesten önce anladığı söylenemez.'),
  ('"Sınavdan önce biraz daha çalışsaydım bu sonucu almazdım." cümlesinden hangisi çıkarılamaz?', 'Konuşan, aldığı sonuçtan memnundur.', ['Konuşan sınava yeterince çalışmamıştır.', 'Konuşan aldığı sonucu beklediğinden düşük bulmaktadır.', 'Konuşan çalışmadığı için pişmandır.'], 'Cümlede yetersiz çalışma ve bunun yol açtığı istenmeyen sonuç için pişmanlık vardır; konuşanın sonuçtan memnun olduğu çıkarılamaz.'),
  ('Yazarlarla ilgili hangi cümlede yakınma ile eleştiri bir arada bulunur?', 'Yazarlar okuru hiç düşünmüyor, kitapçıda okuyacak kitap bulamıyorum.', ['Yazarlarımızın son yıllarda yazdığı romanlar çok beğeniliyor.', 'Bu yazarın kitaplarını her yaz yeniden okurum.', 'Yazarlarımız arasında en çok sevdiğim Sait Faik\'tir.'], 'Yazarların okuru düşünmeden yazdığı yargısı eleştiri, okuyacak kitap bulamamak ise yakınmadır.'),
  ('"Ocağı tütmek" sözü bir aile için kullanıldığında ne anlatılır?', 'Ailenin varlığını sürdürmesi, geçimini sağlaması', ['Evde yangın çıkması', 'Ailenin yemek yapmayı sevmesi', 'Evin bacasının bir an önce temizlenmesi gerektiği'], 'Ocaktan duman çıkması gerçek anlamıyla da düşünülebilir ama asıl kastedilen, ailenin yaşamını sürdürmesidir; bu kinayeli bir anlatımdır.'),
  ('"Bu çocuk tam bir kurt; her işin içinden sıyrılmayı bilir." cümlesinde hangi benzetme türü vardır?', 'Benzetme edatı ve yönü kullanılmadan yapılmış güçlü benzetme', ['"Gibi" edatıyla kurulmuş açık benzetme', 'Gerçek anlamda bir hayvanın tanıtılması', 'Bir hayvanın insan gibi konuşturulduğu ve düşündürüldüğü kişileştirme'], 'Çocuk, "gibi" kullanılmadan doğrudan "kurt" olarak nitelenmiş; yalnız benzeyen ve benzetilen kalmıştır. Bu ağır (güçlü) benzetmedir.'),
  ('Aşağıdaki cümlelerin hangisinde kişileştirme yapılmamıştır?', 'Akşam olunca sokak lambaları yandı.', ['Ağaçlar rüzgârda kollarını sallayıp bizi selamlıyordu.', 'Güneş bulutların arkasına saklanıp utangaçça gülümsedi.', 'Eski ev, yıllardır sahibinin dönmesini bekliyordu.'], 'Lambaların yanması olağan bir olaydır. Diğerlerinde ağaç, güneş ve eve insana özgü davranışlar yüklenmiştir.'),
  ('Aşağıdaki cümlelerin hangisinde kişileştirme ile abartma bir arada kullanılmıştır?', 'Gök gürültüsünden korkan dağlar bile yerinden kaçtı.', ['Gök gürültüsü duyulunca çocuklar içeri koştu.', 'Dağların zirvesi bulutlarla kaplıydı.', 'Fırtına yüzünden bütün otobüs ve uçak seferleri iptal edildi.'], 'Dağlara korku duygusu yüklenmesi kişileştirme, dağların yerinden kaçması ise abartmadır.'),
  ('Aşağıdaki cümlelerin hangisinde "gibi" sözcüğü benzetme için değil, örnek vermek için kullanılmıştır?', 'Ceviz, fındık gibi kuru yemişler kışın enerji verir.', ['Gözleri deniz gibi maviydi.', 'Çocuk, kuş gibi hafifti; kucağa alınca hiç ağırlığı yoktu.', 'Saçları ipek gibi yumuşaktı.'], 'İlk cümlede "gibi", örnek vermek için kullanılmıştır; diğer cümlelerde nitelik bakımından benzetme yapılmıştır.'),
  ('Aşağıdaki cümlelerin hangisinde sözcükler arasında anlamca bir tutarsızlık yoktur?', 'Sabah erkenden yola çıktık, öğleye doğru köye vardık.', ['Tahminen tam olarak üç saat yolculuk yaptık.', 'Gece yarısı tepeye çıkıp güneşin doğuşunu birlikte izledik.', 'Kesinlikle yağmur yağabilir, şemsiyeni al.'], 'İlk cümle tutarlıdır. "Tahminen" ile "tam olarak", "gece yarısı" ile "güneşin doğuşu", "kesinlikle" ile "-abilir" birbiriyle çelişir.'),
  ('"Bu roman, yazarın ilk eseri olmasına karşın onun en olgun kitabıdır; ilk kitabında yazar, henüz deneme aşamasındaydı." cümlesindeki çelişki nereden kaynaklanır?', 'İlk eserin hem en olgun hem de deneme aşamasında yazılmış sayılmasından', ['Romanın yazarının adının verilmemesinden', 'Cümlede karşılaştırma yapılmasından', 'Cümlenin noktalı virgülle iki bağımsız yargıya ayrılmış olmasından'], 'Aynı eser önce en olgun kitap, ardından deneme aşamasının ürünü olarak nitelenmiştir; bu iki yargı bağdaşmaz.'),
  ('Aşağıdaki cümlelerin hangisi biçimce olumlu olduğu hâlde anlamca olumsuzdur?', 'Bu kadar gürültüde ders çalışmak ne mümkün!', ['Bu sessiz odada hiç zorlanmadan, rahatça ders çalışabilirim.', 'Gürültü kesilince derse başladım.', 'Ders çalışmak için kütüphaneye gittim.'], '"Ne mümkün" ünlemiyle yargı olumlu biçimde kurulmuştur ama "mümkün değil" anlamı taşır.'),
  ('"Annesine yalan söylemesi hiç beklenmedik bir şey değildi." cümlesinden hangisi çıkarılır?', 'Yalan söylemesi beklenen bir davranıştı.', ['Yalan söylemesi herkesi şaşırttı.', 'Annesine hiç yalan söylemedi.', 'Annesi yalanı hemen anladı ama yine de onu affetti.'], '"Beklenmedik değildi" çift olumsuzluğu "beklenen bir şeydi" anlamını verir.'),
  ('"Bu kente gelen her yolcu, en az bir kez boğazda vapura binmeden dönmez." cümlesinden hangisi çıkarılabilir?', 'Kente gelenlerin tamamı boğazda vapura biner.', ['Kente gelen yolcuların bir bölümü vapura binmez.', 'Vapur seferleri yalnızca yolcular içindir.', 'Yolcular vapura bir kez bindikten sonra bir daha binmez.'], '"Binmeden dönmez" yapısı, herkesin en az bir kez vapura bindiğini anlatır.'),
  ('"Ünlü yazar, gençliğinde yazdığı şiirleri yıllar sonra yakmak istemiş ama dostları buna engel olmuş." cümlesinden hangisi kesin olarak çıkarılır?', 'Yazarın gençlik şiirleri yakılmamıştır.', ['Yazar şiirlerini yayımlatmaktan hep gurur duymuştur.', 'Yazarın dostları şiirleri hiç beğenmemiştir.', 'Şiirler yazarın ölümünden sonra yakılmıştır.'], 'Dostlar yakmaya engel olduğuna göre şiirler yakılmamıştır. Dostların şiirleri beğenip beğenmediği cümlede yoktur.'),
  ('"Ali dün akşam parkta arkadaşlarıyla buluştu." cümlesinde buluşmanın zamanı vurgulanmak istenirse cümle nasıl kurulmalıdır?', 'Ali parkta arkadaşlarıyla dün akşam buluştu.', ['Dün akşam Ali parkta arkadaşlarıyla buluştu.', 'Ali dün akşam arkadaşlarıyla parkta buluştu.', 'Arkadaşlarıyla Ali dün akşam parkta buluştu.'], 'Vurgulanmak istenen öğe yüklemin hemen önüne getirilir; zaman bildiren "dün akşam" yüklemden hemen önce olmalıdır.'),
  ('"Tıp, pek çok dala ayrılan geniş bir bilim alanıdır." cümlesinde "dal" sözcüğü hangi anlam türüyle kullanılmıştır?', 'Yan anlam', ['Gerçek anlam', 'Terim anlam', 'Sesteş sözcük'], 'Bir bilimin bölümlerine "dal" denmesi, ağaç dalının gövdeden ayrılmasına benzetmeyle oluşan yan anlamdır.'),
  ('"Fırtına, köyün elektrik hatlarını kopardı." ve "Bu haber, onu ailesinden kopardı." cümlelerindeki "koparmak" sözcüğü için hangisi söylenebilir?', 'İlkinde gerçek, ikincisinde mecaz anlamdadır.', ['İkisinde de gerçek anlamdadır.', 'İlkinde mecaz, ikincisinde gerçek anlamdadır.', 'İkisinde de terim anlamında, fizikteki bir kavramı karşılar.'], 'Elektrik hatları fiziksel olarak kopar; ailesinden kopmak ise duygusal bağın kesilmesidir, mecazdır.'),
  ('"Okulun etrafını çevreleyen duvarlar yeniden boyandı." cümlesindeki anlatım kusurunun nedeni nedir?', 'Aynı anlamı taşıyan iki sözün bir arada kullanılması', ['Cümlede yüklemin bulunmaması', 'Karşıt anlamlı iki sözcüğün yan yana gelmesi', 'Bir sözcüğün mecaz anlamda kullanılması'], '"Etraf" ile "çevre" aynı anlamı taşır; "etrafını çevreleyen" ifadesinde gereksiz bir tekrar vardır. "Okulu çevreleyen duvarlar" demek yeterlidir.'),
  ('"Dolu" sözcüğü aşağıdakilerin hangisinde ötekilerden farklı, sesteş bir anlamda kullanılmıştır?', 'Dün akşam yağan dolu bağları perişan etti.', ['Dolu bir bardağı dökmeden taşıdı.', 'Otobüs öyle doluydu ki ikimiz de binemedik.', 'Sepet dolu dolu meyveyle döndü.'], 'Yağış türü olan "dolu", içi boş olmayan anlamındaki "dolu" ile yalnızca ses bakımından aynıdır.'),
  ('Aşağıdakilerin hangisinde soyut bir kavram somutlaştırılarak anlatılmıştır?', 'Umutlarını bir bavula koyup yola çıktı.', ['Bavulunu hazırlayıp yola çıktı.', 'Yola çıkmadan önce biletini aldı.', 'Otogarda bütün arkadaşları gelip onu el sallayarak uğurladı.'], '"Umut" soyut bir kavramdır; bavula konan bir eşya gibi anlatılarak somutlaştırılmıştır.'),
  ('Aşağıdaki atasözü çiftlerinden hangisi birbirine yakın anlamlıdır?', '"Acele işe şeytan karışır." - "Ağır giden yük, tez gider."', ['"Damlaya damlaya göl olur." - "Har vurup harman savurur."', '"Söz gümüşse sükût altındır." - "Söyleyenin ağzında bakla ıslanmaz."', '"İşleyen demir ışıldar." - "Tembele iş buyur, sana akıl öğretsin."'], 'İki atasözü de aceleyle değil, sabırla ve dikkatle iş yapmanın daha iyi sonuç verdiğini anlatır.'),
  ('"Az veren candan, çok veren maldan." atasözü ne anlatır?', 'Az olanağı olanın verdiği az şey, varlıklının verdiği çoktan değerlidir.', ['Az vermek her zaman cimriliktir.', 'Çok veren kişi her zaman daha cömerttir ve verdiği her şey çok daha değerlidir.', 'Bağış yapmamak gerekir.'], 'Yoksulun verdiği az, kendi payından fedakârlık içerir; atasözü bu fedakârlığın değerini vurgular.'),
  ('Aşağıdaki ikilemelerin hangisi, anlamsız bir sözcüğün anlamlı bir sözcükle bir araya gelmesiyle oluşmuştur?', 'kitap mitap', ['ev bark', 'yaşlı başlı', 'konu komşu, eş dost'], '"Mitap" tek başına anlamı olmayan bir sözcüktür; "m" ile kurulan bu tür ikilemeler "ve benzerleri" anlamı katar.'),
  ('"Kar yağışı nedeniyle uçak seferleri iptal edildi." cümlesinde neden yerine amaç bildiren bir cümle kurulmak istenirse hangisi seçilmelidir?', 'Yolcuların güvenliğini korumak için uçak seferleri iptal edildi.', ['Kar yağdığı için uçak seferleri iptal edildi.', 'Kar yağışı yüzünden bütün gün boyunca seferler yapılamadı ve yolcular bekledi.', 'Kar dinerse seferler yeniden başlayacak.'], '"Güvenliği korumak için" ulaşılmak istenen hedefi, yani amacı bildirir; diğerlerinde neden ya da koşul vardır.'),
  ('"Şehirdeki hava kirliliğini azaltmak amacıyla toplu taşıma kullanımı teşvik ediliyor." cümlesinden hangisi çıkarılamaz?', 'Toplu taşıma kullanımı hava kirliliğini artırmaktadır.', ['Şehirde hava kirliliği bir sorun olarak görülmektedir.', 'Toplu taşımanın kirliliği azaltacağı düşünülmektedir.', 'Toplu taşıma kullanımı yetkililerce desteklenmekte ve özendirilmektedir.'], 'Cümle, toplu taşımanın kirliliği azaltmak için desteklendiğini söyler; kirliliği artırdığı yargısı cümleye aykırıdır.'),
  ('Aşağıdaki cümlelerin hangisinde "mi" soru eki koşul anlamı katmıştır?', 'Yağmur başladı mı bütün yollar göle döner.', ['Yağmur başladı mı?', 'Bu yağmur ne zaman başladı?', 'Yağmurun başladığını haberlerde duydun mu?'], '"Başladı mı ... döner" yapısı "başlarsa döner" anlamında koşul bildirir; diğer cümleler gerçek soru cümleleridir.'),
  ('"Annem, çay demlensin diye ocağın altını kıstı." cümlesinde "diye" yerine hangisi getirilirse cümlenin anlamı neden-sonuç ilişkisine dönüşür?', 'demlendiği için', ['demlenmesi için', 'demlensin amacıyla', 'demlenirse'], '"Demlendiği için" gerçekleşmiş bir durumu bildirerek nedeni anlatır; diğerleri amaç ya da koşul bildirir.'),
  ('"Eve döndüğünde masada bir not buldu: \'Seni bekledik, sonra sinemaya gittik.\' Ailesinin birkaç saat sonra döneceğini tahmin etti." Bu sözlerdeki son yargı neye dayanır?', 'Bırakılan nottan yapılan bir çıkarıma', ['Ailesinin telefonla bildirdiği kesin bir bilgiye', 'Tamamen hayal ürünü bir varsayıma', 'Komşulardan duyulan bir söylentiye'], 'Notta dönüş saati yazmaz; sinemaya gidildiği bilgisinden yola çıkılarak ailenin birkaç saat sonra döneceği tahmin edilmiştir. Bu, nottan yapılan bir çıkarımdır.'),
  ('"Bu sabah ilk kez kahvaltıyı ben hazırladım." cümlesinden hangisi çıkarılamaz?', 'Konuşan her sabah kahvaltı hazırlar.', ['Konuşan daha önce hiç kahvaltı hazırlamamıştır.', 'Bu sabah kahvaltıyı konuşan hazırlamıştır.', 'Daha önce kahvaltıyı başkaları hazırlamıştır.'], '"İlk kez" ifadesi daha önce bunun yapılmadığını sezdirir; dolayısıyla her sabah kahvaltı hazırladığı söylenemez.'),
  ('"Ağabeyim bile bu problemi çözemedi." cümlesindeki "bile" sözcüğü hangi örtülü anlamı taşır?', 'Ağabeyin bu tür problemleri genellikle çözebildiğini', ['Ağabeyin matematikten hiç hoşlanmadığını ve dersten kaçtığını', 'Problemin çok kolay olduğunu', 'Ağabeyin problemi çözmeye hiç uğraşmadığını'], '"Bile", beklenmeyen bir durumu vurgular: çözmesi beklenen ağabey bile çözemediyse problem zordur ve ağabey genellikle başarılıdır.'),
  ('"Kardeşim de sonunda gözlük takmaya başladı." cümlesinden hangisi çıkarılamaz?', 'Ailede gözlük takan tek kişi kardeşimdir.', ['Gözlük takan başka kişiler de vardır.', 'Kardeşim önceden, küçükken gözlük takmıyordu.', 'Kardeşim artık gözlük takıyor.'], '"De" başkalarının da gözlük taktığını sezdirir; bu yüzden kardeşin tek gözlüklü olduğu söylenemez.'),
  ('Aşağıdaki cümlelerin hangisinde ön yargı yoktur?', 'Romanı okuduktan sonra yazarın üslubunu ağır buldum.', ['Bu yazarın kitabını okumama gerek yok, kesin kötüdür.', 'Genç yazarlar zaten derinlikli eser yazamaz.', 'Bu yayınevinden çıkan her kitap sıkıcıdır, hiç almam.'], 'İlk cümlede yargı, kitap okunduktan sonra varılmış kişisel bir değerlendirmedir. Diğerlerinde tanımadan peşin hüküm verilmiştir.'),
  ('Aşağıdakilerden hangisinde hem benzetme hem kişileştirme vardır?', 'Ay, bir anne gibi şefkatle uyuyan şehri izliyordu.', ['Ay, gökyüzünde bir tepsi gibi parlıyordu.', 'Ay ışığı denizin üstüne vurmuştu.', 'Bu gece ay, bulutsuz gökyüzünde dolunay hâlindeydi.'], 'Ay anneye benzetilmiş (benzetme) ve ona şefkatle izleme gibi insani bir davranış verilmiştir (kişileştirme).'),
  ('"Bu konuda daha çok kitap okumalısın." ve "Keşke bu konuda daha çok kitap okusaydım." cümlelerinin anlamca farkı nedir?', 'İlki başkasına öneri, ikincisi kendine yönelik pişmanlıktır.', ['İkisi de başkasına yöneltilmiş birer öneridir.', 'İlki pişmanlık, ikincisi öneri bildirir.', 'İkisi de konuyla ilgili kesin ve doğrulanabilir bir bilgi aktarır.'], '"-malısın" karşıdakine yönelik bir öneridir; "keşke ... -saydım" ise konuşanın geçmişe dönük pişmanlığıdır.'),
  ('"Deneme, yazarın herhangi bir konudaki kişisel görüşlerini kesin yargılara varmadan, samimi bir dille anlattığı yazı türüdür." cümlesine göre denemenin özelliği hangisi değildir?', 'Kesin ve kanıtlanmış yargılar sunması', ['Kişisel görüşlere dayanması', 'Samimi bir dille yazılması', 'Herhangi bir konuyu, sınırlama olmadan ele alabilmesi'], 'Tanımda denemenin kesin yargılara varmadan yazıldığı belirtilmiştir; dolayısıyla kesin yargı sunması bu türün özelliği değildir.'),
  ('Aşağıdaki cümlelerin hangisinde mantık hatası yoktur?', 'Toplantıya katılanların yarısı öğretmen, yarısı veliydi.', ['Toplantıya katılan herkes öğretmendi, velilerin çoğu da gelmişti.', 'Salon bomboştu, oturacak yer bulamadık.', 'Hiç konuşmadan saatlerce sohbet ettik.'], 'İlk cümle tutarlıdır. Diğerlerinde "herkes öğretmen" ile "veliler geldi", "bomboş" ile "yer bulamadık", "konuşmadan" ile "sohbet" çelişir.'),
  ('"Sağlıklı beslenmeyen bir insanın uzun süre zinde kalması beklenemez." yargısına anlamca en yakın cümle hangisidir?', 'Zinde kalmak için sağlıklı beslenmek gerekir.', ['Sağlıklı beslenen herkes uzun yaşar.', 'Zindelik beslenmeyle ilgili değildir.', 'Kötü beslenen insanlar her zaman çok enerjiktir.'], 'Asıl cümle zindeliği sağlıklı beslenme koşuluna bağlar; ilk seçenek bu ilişkiyi korur. "Uzun yaşar" ise cümlede olmayan bir yargıdır.'),
  ('"Bu kitabı bitirdiğimde, ilk sayfasını açtığım günkü insan olmadığımı fark ettim." cümlesiyle anlatılmak istenen hangisidir?', 'Kitap, okuyanı değiştiren bir etki bırakmıştır.', ['Kitabı başkası da okumuştur.', 'Kitabın ilk sayfası eksiktir.', 'Kitabı bitirmek, beklediğinden çok daha uzun sürmüştür.'], 'Okurun kendini kitabı açtığı andaki kişi olarak görmemesi, kitabın onda bir değişim yarattığını anlatır.'),
  ('"Her başarının arkasında görünmeyen bir emek yatar." cümlesinden aşağıdakilerden hangisi çıkarılamaz?', 'Başarıların çoğu tesadüf eseridir.', ['Başarı çaba gerektirir.', 'Başarının ardındaki emek her zaman görülmez.', 'Başarıyı yalnızca sonucuna bakarak değerlendirmek eksik olur.'], 'Cümle başarının emeğe dayandığını vurgular; başarının tesadüf olduğu yargısı bununla çelişir.'),
  ('"Dil" sözcüğü aşağıdakilerin hangisinde "suya doğru uzanan ince, uzun kara parçası" anlamında kullanılmıştır?', 'Gölün ortasına doğru uzanan dilin ucunda bir fener vardı.', ['Çocuk, dondurmayı diliyle yaladı.', 'Türkçe, eklemeli bir dildir.', 'Bu yazarın dili çok akıcı.'], 'Coğrafyada suya doğru uzanan ince, uzun kara parçasına "dil" denir; bu, organa benzetmeyle oluşmuş bir yan anlamdır.'),
  ('Aşağıdaki cümlelerin hangisinde "sonuç" yerine "neden" sözcüğü kullanılması gerekirken yanlışlık yapılmıştır?', 'Kazanın sonucu, sürücünün kırmızı ışıkta geçmesiydi.', ['Kazanın sonucunda iki kişi yaralandı.', 'Sınavın sonucu yarın açıklanacak.', 'Uzun bir çabanın sonucunda başarıya ulaştı.'], 'Kırmızı ışıkta geçmek kazanın sonucu değil, nedenidir; sözcük anlamına uygun kullanılmamıştır.'),
  ('"Ninemin çıtır çıtır kızarttığı ekmekler sabah kahvaltısının vazgeçilmeziydi." cümlesindeki "çıtır çıtır" ikilemesinin oluşumuyla ilgili hangisi doğrudur?', 'Bir sesin yansımasından türemiş sözcüğün tekrarıyla oluşmuştur.', ['Karşıt anlamlı iki ayrı sözcüğün bir araya gelmesiyle oluşmuştur.', 'Biri anlamsız iki sözcükten oluşmuştur.', 'Eş anlamlı iki farklı sözcükten oluşmuştur.'], '"Çıtır", gevrek bir şeyin kırılırken çıkardığı sesin yansımasıdır; aynı sözcüğün tekrarıyla ikileme kurulmuş ve ekmeğin gevrekliği anlatılmıştır.'),
  ('"Koyu bir sessizlik çöktü odaya." cümlesindeki aktarmayla ilgili hangisi doğrudur?', 'Görmeyle ilgili bir nitelik, işitmeyle ilgili bir kavrama aktarılmıştır.', ['Tatla ilgili bir nitelik, kokuya aktarılmıştır.', 'Sözcükler gerçek anlamlarıyla kullanılmıştır.', 'Dokunmayla ilgili bir nitelik, kokuya aktarılmıştır.'], '"Koyu" renk bildirir ve görmeyle algılanır; sessizlik ise işitmeyle ilgilidir.'),
  ('"Ortak kasadaki parayı o savurgan adama teslim etmekle ... ; bir hafta içinde hepsini harcadı." cümlesinde boşluğa hangisi uygun düşer?', 'kurda kuzu emanet ettik', ['iki kuşu bir taşla vurduk', 'gemileri yaktık', 'suyu tersine akıttık'], '"Kurda kuzu emanet etmek", bir şeyi ona zarar verecek kişiye teslim etmektir; parayı savurgan birine vermek bu duruma uyar.'),
  ('"Üzüm yiyip bağını sormamak" deyimi hangi tutumu anlatır?', 'Bir şeyden yararlanırken ayrıntılarla ilgilenmemek', ['Bağ bozumunda çok çalışmak', 'Meyvelerin nereden geldiğini araştırmak', 'Başkasının malına göz dikmek'], 'Deyim, elde edilen yarara bakıp kaynağını ya da ayrıntısını kurcalamamayı anlatır.'),
  ('Aşağıdaki cümlelerden hangisi anlam ilişkisi bakımından ötekilerden farklıdır?', 'Daha iyi görebilmek için ön sıraya oturdu.', ['Gözleri bozulduğu için gözlük taktı.', 'Sabaha kadar çalıştığından çok yorgundu.', 'Yollar buz tuttuğu için kaza oldu.'], 'İlk cümlede amaç-sonuç, diğerlerinde ise gerçekleşmiş bir nedene bağlı neden-sonuç ilişkisi vardır.'),
  ('Aşağıdaki cümlelerden hangisinde ötekilerden farklı olarak koşul anlamı yoktur?', 'Ödevini bitirince parka gitti.', ['Ödevini bitirirsen parka gidebilirsin.', 'Ödevini bitirmedikçe parka gidemezsin.', 'Ödevini bitirdiğin takdirde parka gidersin.'], '"Bitirince" zaman bildirir ve gerçekleşmiş bir durumu anlatır; diğerlerinde parka gitmek ödevi bitirme koşuluna bağlanmıştır.'),
  ('Aşağıdaki cümlelerin hangisi biçim ve anlam bakımından olumsuzdur?', 'Bu yaz tatile çıkamadık.', ['Bu yaz tatile çıkmadık değil.', 'Tatile çıkmamak elimizde değildi.', 'Tatile çıkmayan kalmadı.'], '"Çıkamadık" hem biçim hem anlam olarak olumsuzdur. Diğerlerinde biçimce olumsuzluk olsa da anlam olumludur.'),
  ('"Yazarın son romanı, ilk romanına göre çok daha az satış yaptı ama eleştirmenlerden daha fazla övgü aldı." cümlesinden hangisi kesin olarak çıkarılır?', 'Satış başarısı ile eleştirmen beğenisi her zaman aynı yönde olmayabilir.', ['Yazarın ilk romanı eleştirmenlerce hiç beğenilmemiştir.', 'Son roman hiç okunmamıştır.', 'Eleştirmenler yalnızca çok satan kitapları över.'], 'Az satan son romanın daha çok övülmesi, satış ile eleştirmen beğenisinin farklı yönlerde olabileceğini gösterir. İlk romanın hiç beğenilmediği kesin değildir.'),
  ('"Rehber, bu köprünün şehrin en etkileyici yapısı olduğunu söyledi." cümlesi ile "Köprü, nehrin en dar yerine kurulmuştur." cümlesi arasındaki fark nedir?', 'İlki bir kişinin değerlendirmesini aktarır, ikincisi doğrudan bir bilgi verir.', ['İlki tamamen bir tahmindir, ikincisi öznel bir yargıdır.', 'İkisi de kişisel beğeni bildiren öznel yargılardır.', 'İlki bir tanım, ikincisi bir öneridir.'], 'Birinci cümle rehberin kişisel değerlendirmesini aktarır; ikincisi ise gözlemle doğrulanabilecek bir bilgidir.'),
  ('Aşağıdaki cümlelerin hangisinde birbirine karşıt iki kavram bir arada kullanılmamıştır?', 'Bu yolculuk uzun ve yorucu geçti.', ['İyiyi kötüden ayırmayı öğrenmeliyiz.', 'Gelenler de gidenler de vedalaştı.', 'Yaşlısı genci, bu bayramda bir araya geldi.'], '"Uzun" ve "yorucu" aynı yönde iki niteliktir. Diğer cümlelerde iyi-kötü, gelen-giden, yaşlı-genç karşıtlıkları vardır.'),
  ('Aşağıdaki sözcüklerden hangisi ötekilerden farklı olarak somut bir varlığı karşılar?', 'gölge', ['cesaret', 'özgürlük', 'adalet'], 'Gölge gözle görülebildiği için somuttur; cesaret, özgürlük ve adalet ise soyut kavramlardır.'),
  ('"Ayrılık acısı, bütün evin üzerine ağır bir yük gibi çökmüştü." cümlesinde hangi anlatım vardır?', 'Soyut bir duygu, somut bir nesneye benzetilerek anlatılmıştır.', ['Somut bir nesne, soyut bir kavrama benzetilmiştir.', 'Evin gerçekten bir yük altında kaldığı anlatılmıştır.', 'Cümlede yalnızca gerçek anlamlı sözcükler vardır.'], 'Soyut olan "ayrılık acısı", somut "ağır bir yük"e benzetilerek daha etkili anlatılmıştır.'),
  ('"Annem bu pastayı sabah yaptı." cümlesinde pastayı yapan kişi değil de yapıldığı zaman vurgulanmışsa, aşağıdaki sorulardan hangisinin yanıtı bu cümledir?', 'Annen bu pastayı ne zaman yaptı?', ['Bu pastayı kim yaptı?', 'Annen sabah ne yaptı?', 'Annen pastayı nerede yaptı?'], 'Vurgulanan öge sorunun yanıtıdır; yüklemden önceki "sabah" zaman bildirir ve "ne zaman" sorusunu karşılar.'),
  ('Aşağıdaki cümlelerin hangisinde abartma yoktur?', 'Yağmur sabaha kadar durmadan yağdı.', ['Gözyaşları sel olup aktı.', 'Bu sıcakta taşlar bile eriyor.', 'Sana bin kere söyledim, dinlemedin.'], 'Yağmurun sabaha kadar yağması olağan bir durumdur; diğerlerinde gerçeği aşan anlatımlar vardır.'),
  ('"Bu yıl yeterince yağmur yağmadığından buğday rekoltesi düştü." cümlesiyle aynı anlam ilişkisini taşıyan cümle hangisidir?', 'Fazla şeker tükettiği için dişleri çürüdü.', ['Dişlerinin çürümemesi için şekeri azalttı.', 'Şekeri azaltırsan dişlerin sağlıklı olur.', 'Dişleri, kardeşininkinden daha sağlamdır.'], 'Verilen cümlede neden-sonuç ilişkisi vardır; "şeker tükettiği için dişleri çürüdü" cümlesi de aynı ilişkiyi taşır.'),
  ('"Bu sorunu çözmenin tek yolu ... ." cümlesi aşağıdakilerden hangisiyle tamamlanırsa diğerlerinden farklı olarak bir öneri anlamı kazanmaz?', 'yıllar önce tartışılmıştı', ['herkesin sorumluluk almasıdır', 'taraflarla açıkça konuşmaktır', 'sabırla çalışmaya devam etmektir'], '"Yıllar önce tartışılmıştı" geçmişteki bir olayı bildirir; diğer seçenekler sorunun çözümüne yönelik yol gösterir.'),
  ('"Teknolojik gelişmeler iletişimi hızlandırdı; ... insanlar arasındaki yüz yüze görüşmeler azaldı." cümlesinde boşluğa hangisi getirilmelidir?', 'ne var ki', ['çünkü', 'örneğin', 'üstelik'], 'Hızlanan iletişim olumlu, azalan yüz yüze görüşme olumsuz bir durumdur; iki yargı arasındaki bu karşıtlık "ne var ki" ile kurulur. "Çünkü" ise neden-sonuç ilişkisini ters kurar.'),
  ('"Tez canlı" bir sıfat iken bugün "tez" sözcüğü akademik bir çalışmayı da anlatır. Aşağıdakilerden hangisi bu iki kullanım arasındaki ilişkiyi doğru açıklar?', 'Aynı biçimde yazılan, anlamca ilgisiz iki ayrı sözcüktür.', ['İkisi de aynı sözcüğün mecaz anlamıdır.', 'Birincisi ikincisinin terim anlamıdır.', 'İkisi de eş anlamlı sözcüklerdir.'], '"Çabuk" anlamındaki Farsça kökenli "tez" ile "savunulan görüş, bilimsel çalışma" anlamındaki Fransızca kökenli "tez" sesteştir; aralarında anlam bağı yoktur.'),
  ('"En" sözcüğü aşağıdaki cümlelerin hangisinde üstünlük bildirmemektedir?', 'Kumaşın eni iki metreden biraz fazlaydı.', ['Sınıfın en uzun boylu öğrencisi oydu.', 'Bu yolun en tehlikeli yeri şu viraj.', 'Köyün en yaşlı insanı yüz yaşındaydı.'], '"Kumaşın eni" genişlik anlamındadır; sesteş bir addır. Diğer cümlelerde "en" üstünlük bildirir.'),
  ('"Bu dağ, bölgedeki dağların en yükseği değil ama en zor tırmanılanıdır." cümlesinden hangisi çıkarılabilir?', 'Bölgede bu dağdan daha yüksek en az bir dağ vardır.', ['Bölgedeki bütün dağlar bu dağdan alçaktır.', 'Bu dağa tırmanmak en kolay iştir.', 'Bölgedeki en yüksek dağa tırmanmak en zorudur.'], 'Dağın en yüksek olmadığı söylendiğine göre ondan yüksek en az bir dağ vardır; zorluk bakımından ise en üst düzeydedir.'),
  ('"Hapse girdi" demek yerine "bir süre devlet misafiri oldu" denmesi hangi anlatım biçimine örnektir?', 'Hoş olmayan bir durumun yumuşatılarak anlatılması', ['Bir durumun abartılarak anlatılması', 'Bir sözcüğün terim anlam kazanması', 'Bir kavramın tanımlanması'], 'Söylenmesi rahatsız edici bir durumu daha hoş bir sözle anmak güzel adlandırmadır (örtmece); burada hafif bir alay da sezilir.'),
  ('Aşağıdakilerin hangisinde güzel adlandırma yoluyla bir kavram yumuşatılmamıştır?', 'Yaşlı adam bastonuna dayanarak yürüdü.', ['Büyükannem gözlerine perde indiği için okuyamıyor.', 'Komşumuzun eşi geçen yıl Hakk\'a yürüdü.', 'Yaşlı adamın kulakları biraz ağırlaşmış.'], '"Hakk\'a yürümek" (ölmek), "kulakları ağırlaşmak" (sağırlaşmak) yumuşatıcı anlatımlardır; ilk seçenek ise olağan bir durumu doğrudan anlatır. "Gözüne perde inmek" de görme kaybını yumuşatır.'),
  ('Aşağıdaki cümlelerin hangisi bir yakınma değil, durum tespitidir?', 'Şehrin nüfusu son on yılda yüzde yirmi arttı.', ['Şehir o kadar kalabalıklaştı ki nefes alacak yer kalmadı.', 'Bu kalabalıkta insan kendini kaybolmuş hissediyor.', 'Her yer kalabalık, artık sokağa çıkmak istemiyorum.'], 'Nüfus artışını sayısal olarak bildiren cümle yalnızca bir durumu tespit eder; diğerlerinde kalabalıktan şikâyet vardır.'),
  ('Öğretmen, "Yarınki geziye herkes kimliğini getirsin." dedi. Bu cümlenin dolaylı anlatımla, bir gün sonra aktarılmış doğru biçimi hangisidir?', 'Öğretmen, o günkü geziye herkesin kimliğini getirmesini söylemişti.', ['Öğretmen, yarınki geziye kimliğini getirdiğini söyledi.', 'Öğretmen: "Yarınki geziye herkes kimliğini getirsin." dedi.', 'Öğretmen, geziye kimsenin kimlik getirmemesini istedi.'], 'Söz bir gün sonra aktarıldığında "yarınki" ifadesi "o günkü" olur ve emir "getirmesini söyledi" yapısına dönüşür. Tırnaklı seçenek doğrudan anlatımdır.'),
  ('"Pencereden içeri giren sabah güneşi masanın üstündeki çiçekleri ısıtıyordu." cümlesindeki sözcüklerle ilgili hangisi doğrudur?', 'Sözcükler gerçek anlamlarıyla kullanılmıştır.', ['"Isıtmak" mecaz anlamdadır.', '"Güneş" kişileştirilmiştir.', '"Çiçek" terim anlamıyla kullanılmıştır.'], 'Güneşin çiçekleri ısıtması fiziksel, gerçek bir olaydır; cümlede mecaz ya da kişileştirme yoktur.'),
  ('"Kar, bütün gece yağdı ve sabah sokaklar bembeyaz oldu." cümlesinde mecaz anlamlı sözcük olup olmadığıyla ilgili hangisi doğrudur?', 'Mecaz anlamlı bir sözcük yoktur.', ['"Bembeyaz" sözcüğü mecaz anlamdadır.', '"Yağmak" eylemi mecaz anlamdadır.', '"Sokak" sözcüğü ad aktarmasıyla kullanılmıştır.'], 'Karın yağması ve sokakların beyaza bürünmesi gerçek olaylardır; sözcükler gerçek anlamlarındadır.'),
  ('"Diyelim ki haklısın; peki bu, sana bağırma hakkı verir mi?" cümlesinde konuşan nasıl bir yol izlemiştir?', 'Karşıdakinin görüşünü geçici olarak kabul edip yine de ona itiraz etmiştir.', ['Karşıdakinin kesinlikle haklı olduğunu kabul edip özür dilemiştir.', 'Karşıdakinden bilgi istemiştir.', 'Bir olayın nedenini açıklamıştır.'], '"Diyelim ki" ile haklılık varsayılmış, ardından sözde soruyla bağırmanın yanlış olduğu vurgulanmıştır.'),
  ('"Bu haberi bana dün akşam kardeşim telefonla verdi." cümlesinde haberi verenin kim olduğu vurgulanmak istenirse cümlenin doğru sıralanışı hangisidir?', 'Bu haberi bana dün akşam telefonla kardeşim verdi.', ['Kardeşim bu haberi bana dün akşam telefonla verdi.', 'Bu haberi kardeşim bana telefonla dün akşam verdi.', 'Dün akşam kardeşim bu haberi telefonla bana verdi.'], 'Vurgulanacak öğe yüklemin hemen önüne gelir; "kardeşim" öznesi "verdi" yükleminden hemen önce olmalıdır.'),
  ('"Ödevini bitirmeden dışarı çıkma, sonra pişman olursun." cümlesinde hangi iki anlam bir aradadır?', 'Yasaklama ve uyarı', ['Rica ve teşekkür', 'Övgü ve umut', 'Özlem ve sitem'], '"Çıkma" olumsuz emirle yasaklama, "pişman olursun" ile de olası bir sonuca karşı uyarı yapılmıştır.'),
  ('Aşağıdaki cümlelerin hangisinde tekrarlanan sözcük, bir sesi değil bir görüntüyü anlatmaktadır?', 'Gözleri sevinçten ışıl ışıl parlıyordu.', ['Kapı rüzgârda gıcır gıcır öttü.', 'Çaydanlık fokur fokur kaynıyordu.', 'Kuşlar cıvıl cıvıl ötüşüyordu.'], '"Işıl ışıl" bir sesi değil, parıltıyı anlatır. Gıcır, fokur ve cıvıl ise işitilen seslerin yansımasıdır.'),
  ('Aşağıdaki cümlelerin hangisinde parça-bütün ilişkisine dayalı bir ad aktarması vardır?', 'Bu köyde her ocaktan bir genç askere gitti.', ['Köyün kenarında küçük bir ocak vardı.', 'Ocağın üstünde çaydanlık kaynıyordu.', 'Ocakta odun çatırdıyordu.'], '"Ocak" burada evin bir parçası olarak bütün aileyi, haneyi anlatır; diğer cümlelerde gerçek anlamlı ocak vardır.'),
  ('"Sanat, sanatçının iç dünyasını yansıttığı ölçüde değerlidir." ile "Sanat, insanın duygu ve düşüncelerini estetik bir biçimde dile getirme etkinliğidir." cümleleri karşılaştırıldığında hangisi söylenebilir?', 'İkincisi tanım, ilki ise bir değer yargısıdır.', ['İkisi de birer tanımdır.', 'İlki tanım, ikincisi değer yargısıdır.', 'İkisi de birer öneridir.'], 'İkinci cümle sanatın ne olduğunu açıklar; ilki ise sanatın değerini belirli bir ölçüte bağlayan kişisel bir yargı bildirir.'),
  ('"Kim bilir, belki bir gün bu çocuk büyük bir bilim insanı olur." cümlesindeki "kim bilir" sözü için hangisi doğrudur?', 'Soru biçiminde olsa da yanıt beklemez, olasılık anlamı katar.', ['Bir bilgiyi öğrenmek için sorulmuş gerçek bir sorudur.', 'Kesinlik bildirir.', 'Bir kişiye seslenmek için kullanılmıştır.'], '"Kim bilir" kalıplaşmış bir sözde sorudur; geleceğe ilişkin belirsizliği ve olasılığı anlatır.'),
  ('Aşağıdaki cümlelerin hangisinde "bile" sözcüğü "beklenmediği hâlde" anlamı katarak örtülü bir anlam oluşturmuştur?', 'Sınıfın en sessiz öğrencisi bile tartışmaya katıldı.', ['Sınıfın en sessiz öğrencisi de tartışmaya katıldı.', 'Sınıfın en sessiz öğrencisi tartışmaya katılmadı.', 'Sınıfın en sessiz öğrencisi tartışmayı dinledi.'], '"Bile", katılması beklenmeyen birinin katıldığını sezdirir; tartışmanın herkesi etkilediği de anlaşılır.'),
  ('"Ateş olsa cürmü kadar yer yakar." sözü kimin için söylenir?', 'Etkisi ve gücü çok sınırlı olan biri için', ['Çok tehlikeli ve güçlü biri için', 'Ateşle oynayan bir çocuk için', 'İtfaiyede çalışan biri için'], 'Söz, birinin ne yaparsa yapsın büyük bir zarar veremeyeceğini, etkisinin küçük olduğunu anlatır.'),
];
